func ptrSettlementControl(p unsafe.Pointer, c int32) any {
	r := (*settlementcontrol.SettlementControl)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.PayPeriodFrequency))
	case 4:
		return (*int64)(unsafe.Pointer(&r.PeriodEndDayOfWeek))
	case 5:
		return (*int64)(unsafe.Pointer(&r.PayDelayDays))
	case 6:
		return (*string)(unsafe.Pointer(&r.PayTrigger))
	case 7:
		return &r.AutoGenerateBatches
	case 8:
		return &r.AutoApproveClean
	case 9:
		return &r.AutoAttachAccruals
	case 10:
		return &r.AutoPostOnApprove
	case 11:
		return &r.AllowNegativeNet
	case 12:
		return &r.VarianceThresholdPct
	case 13:
		return (*int64)(unsafe.Pointer(&r.VarianceLookbackWeeks))
	case 14:
		return &r.DefaultEscrowInterestRate
	case 15:
		return (*int64)(unsafe.Pointer(&r.EscrowInterestFrequencyMonths))
	case 16:
		return &r.RequireSeparateApprover
	case 17:
		return &r.Version
	case 18:
		return &r.CreatedAt
	case 19:
		return &r.UpdatedAt
	}
	return nil
}

